const outputItems = [];
const inputItem = $input.first();
const binaryData = inputItem.binary || {};
const mailId = inputItem.json.id || 'unknown';
let index = 0;

for (const [binaryKey, binaryValue] of Object.entries(binaryData)) {
  if (!binaryKey.startsWith('attachment_')) continue;

  const fileName = (binaryValue.fileName || '').toLowerCase();
  const mimeType = (binaryValue.mimeType || '').toLowerCase();
  const fileExtension = (binaryValue.fileExtension || '').toLowerCase();

  const istPDF =
    mimeType === 'application/pdf' ||
    fileName.endsWith('.pdf') ||
    fileExtension === 'pdf';

  const istSignierteDatei =
    mimeType === 'multipart/signed' ||
    mimeType === 'application/pkcs7-mime' ||
    mimeType === 'application/x-pkcs7-mime' ||
    mimeType === 'application/pkcs7-signature' ||
    mimeType === 'application/x-pkcs7-signature' ||
    fileName.endsWith('.p7m') ||
    fileExtension === 'p7m';

  if (!istPDF && !istSignierteDatei) continue;

  const attachment_id = `${mailId}_${index}`;
  const mergeKey = attachment_id;

  const outputFileName = istPDF
    ? binaryValue.fileName
    : (binaryValue.fileName || `attachment_${index}.p7m`).replace(/\.p7m$/i, '.pdf');

  outputItems.push({
    json: {
      ...inputItem.json,
      mail_id: mailId,
      attachment_id,
      attachment_index: index,
      fileName: binaryValue.fileName,
      originalFileName: binaryValue.fileName,
      outputFileName,
      mimeType,
      originalMimeType: mimeType,
      fileExtension,
      istPDF,
      istSignierteDatei,
      brauchtEntpackung: istSignierteDatei && !istPDF,
      inputPath: `/home/node/.n8n-files/${mergeKey}.p7m`,
      outputPath: `/home/node/.n8n-files/${mergeKey}.pdf`,
      mergeKey,
      originalBinaryKey: binaryKey,
    },
    binary: { data: binaryValue },
  });

  index++;
}

if (outputItems.length === 0) {
  return [{
    json: {
      ...inputItem.json,
      mail_id: mailId,
      attachment_id: `${mailId}_none`,
      noValidAttachments: true,
      routeTarget: 'fallback',
      fallbackReason: 'no_valid_attachment',
      ocr_status: 'failed',
      ocr_error: 'Keine PDF- oder P7M-Anhänge in der Mail gefunden.',
    },
  }];
}

return outputItems;

