const item = $input.first();

return [{
  json: {
    ...item.json,
    hasBinary: !!item.binary,
    binaryKeys: Object.keys(item.binary || {}),
    inputPath: item.json.inputPath,
    brauchtEntpackung: item.json.brauchtEntpackung,
  },
  binary: item.binary,
}];

const fs = require('fs');

const item = $input.first();
const inputPath = item.json.inputPath;
const outputPath = item.json.outputPath;

const PDF_PATTERNS = [
  /Content-Type:\s*application\/octet-stream;\s*name="[^"]+\.pdf"[\s\S]*?Content-Transfer-Encoding:\s*base64[\s\S]*?\r?\n\r?\n([\s\S]*?)(?=\r?\n--)/i,
  /Content-Type:\s*application\/pdf(?:;\s*name="[^"]+")?[\s\S]*?Content-Transfer-Encoding:\s*base64[\s\S]*?\r?\n\r?\n([\s\S]*?)(?=\r?\n--)/i,
  /Content-Type:\s*application\/x-pdf[\s\S]*?Content-Transfer-Encoding:\s*base64[\s\S]*?\r?\n\r?\n([\s\S]*?)(?=\r?\n--)/i,
  /name="[^"]+\.pdf"[\s\S]*?Content-Transfer-Encoding:\s*base64[\s\S]*?\r?\n\r?\n([\s\S]*?)(?=\r?\n--)/i,
  /filename="[^"]+\.pdf"[\s\S]*?Content-Transfer-Encoding:\s*base64[\s\S]*?\r?\n\r?\n([\s\S]*?)(?=\r?\n--)/i,
];

function extractPdfBuffer(raw) {
  for (const pattern of PDF_PATTERNS) {
    const match = raw.match(pattern);
    if (!match) continue;
    const base64Body = match[1].replace(/\r?\n/g, '').replace(/\s/g, '');
    const buffer = Buffer.from(base64Body, 'base64');
    if (buffer.length > 5 && buffer.slice(0, 5).toString() === '%PDF-') {
      return { buffer, pattern: pattern.source.slice(0, 40) };
    }
  }
  return null;
}

function fail(reason) {
  return [{
    json: {
      ...item.json,
      decryptFailed: true,
      routeTarget: 'fallback',
      fallbackReason: 'p7m_extract_failed',
      decrypt_error: reason,
    },
    binary: item.binary,
  }];
}

try {
  const raw = fs.readFileSync(inputPath, 'utf8');
  const extracted = extractPdfBuffer(raw);

  if (!extracted) {
    return fail('Keine PDF per Base64 in P7M/S-MIME gefunden (unterstützte Formate: octet-stream, application/pdf, x-pdf).');
  }

  fs.writeFileSync(outputPath, extracted.buffer);

  return [{
    json: {
      ...item.json,
      decryptFailed: false,
      p7mEntpackt: true,
      detectedContent: extracted.pattern,
      outputPath,
      extractedPdfSize: extracted.buffer.length,
    },
    binary: item.binary,
  }];
} catch (e) {
  return fail(e.message);
}

const item = $input.first();

item.binary.data.mimeType = 'application/pdf';
item.binary.data.fileExtension = 'pdf';
item.binary.data.fileName =
  item.json.outputFileName || `${item.json.mergeKey}.pdf`;

item.json.fileName = item.binary.data.fileName;
item.json.mimeType = 'application/pdf';
item.json.fileExtension = 'pdf';
item.json.istPDF = true;
item.json.brauchtEntpackung = false;

return [item];

const originalItems = $('Convert attachments to seperate items').all();
const inputItems = $input.all();

const ROUTES = [
  { id: 'invest4', patterns: [/acribo\s*invest\s*(iv|4)/i] },
  { id: 'invest2', patterns: [/acribo\s*invest\s*(ii|2)/i] },
  { id: 'invest', patterns: [/acribo\s*invest/i] },
  { id: 'grundbesitz', patterns: [/acribo\s*grundbesitz/i] },
  { id: 'energie', patterns: [/acribo\s*energie/i] },
  { id: 'service', patterns: [/acribo\s*service/i] },
  { id: 'kroepcke', patterns: [/kr[öo]pcke|caf[eé]\s*am\s*kr[öo]pcke/i] },
  { id: 'bunke', patterns: [/bunke|ingunde\s*bunke/i] },
  { id: 'gmbh', patterns: [/acribo\s*gmbh/i] },
];

function collectText(value) {
  const parts = [];
  const walk = (obj) => {
    if (obj == null) return;
    if (typeof obj === 'string') { parts.push(obj); return; }
    if (Array.isArray(obj)) { obj.forEach(walk); return; }
    if (typeof obj === 'object') Object.values(obj).forEach(walk);
  };
  walk(value);
  return parts.join(' ');
}

function findRoute(extracted) {
  const customerText = collectText(extracted?.customer_information);
  for (const route of ROUTES) {
    if (route.patterns.some((p) => p.test(customerText))) return route.id;
  }
  const fullText = collectText(extracted);
  for (const route of ROUTES) {
    if (route.patterns.some((p) => p.test(fullText))) return route.id;
  }
  return 'fallback';
}

function resolveOriginal(item, index) {
  return (
    originalItems[index] ||
    originalItems.find((o) => o.json.mergeKey === item.json.mergeKey) ||
    originalItems.find((o) => o.json.attachment_id === item.json.attachment_id)
  );
}

function buildFallback(original, item, reason, extra = {}) {
  return {
    json: {
      ...original.json,
      routeTarget: 'fallback',
      ocrFailed: true,
      fallbackReason: reason,
      ocr_status: extra.ocr_status || 'failed',
      ocr_error: extra.ocr_error || null,
      detected_customer: extra.detected_customer || null,
      detected_merchant: extra.detected_merchant || null,
    },
    binary: original.binary,
  };
}

return inputItems.map((item, index) => {
  const original = resolveOriginal(item, index);
  if (!original) {
    throw new Error(`Kein Original-Anhang für Item ${index} gefunden.`);
  }

  if (item.json.decryptFailed || item.json.routeTarget === 'fallback') {
    return buildFallback(original, item, item.json.fallbackReason || 'decrypt_failed', {
      ocr_error: item.json.decrypt_error || null,
    });
  }

  const provider = item.json['openai/gpt-4o'] || {};
  const extracted = provider.extracted_data?.[0];
  const httpError = item.json.error?.message || item.json.message;
  const providerError = provider.error?.message || (typeof provider.error === 'string' ? provider.error : null);
  const hasError =
    !!httpError ||
    !!providerError ||
    !extracted ||
    (provider.status && provider.status !== 'success');

  if (hasError) {
    return buildFallback(original, item, 'ocr_failed', {
      ocr_status: provider.status || 'error',
      ocr_error: providerError || httpError || 'OCR fehlgeschlagen (z.B. verschlüsselte PDF)',
    });
  }

  const routeTarget = findRoute(extracted);

  if (routeTarget === 'fallback') {
    return buildFallback(original, item, 'no_company_match', {
      ocr_status: provider.status || 'success',
      detected_customer: extracted.customer_information?.name || null,
      detected_merchant: extracted.merchant_information?.name || null,
    });
  }

  return {
    json: {
      ...original.json,
      routeTarget,
      ocrFailed: false,
      fallbackReason: null,
      ocr_status: provider.status || 'success',
      detected_customer: extracted.customer_information?.name || null,
      detected_merchant: extracted.merchant_information?.name || null,
    },
    binary: original.binary,
  };
});

